# 28. Topic 검증

```ts
export function validateTopicIds(
  documents: readonly ContentDocument[],
  validTopicIds: ReadonlySet<string>,
): ValidationIssue[] {
  return documents.flatMap(
    (document): ValidationIssue[] => {
      if (
        validTopicIds.has(
          document.topicId,
        )
      ) {
        return [];
      }

      return [{
        ruleId: "content/unknown-topic",
        severity:
          document.topicId ===
          "unclassified"
            ? "warning"
            : "error",
        documentId: document.id,
        sourcePath:
          document.sourcePath,
        field: "topic",
        message:
          `Unknown topic ID ` +
          `"${document.topicId}".`,
      }];
    },
  );
}
```

Migration 기간에는 `unclassified`를 warning으로 허용할 수 있다.

신규 문서에서는 error로 강화할 수 있다.

---

# 29. Relation 대상 검증

```ts
export function collectRelationIds(
  document: ContentDocument,
): string[] {
  return [
    ...document.relations.prerequisites,
    ...document.relations.next,
    ...document.relations.related,
    ...(document.relations.supersededBy
      ? [
          document.relations
            .supersededBy,
        ]
      : []),
  ];
}
```

```ts
export function validateRelationTargets(
  documents: readonly ContentDocument[],
): ValidationIssue[] {
  const knownIds =
    new Set(
      documents.map(
        (document) => document.id,
      ),
    );

  const issues: ValidationIssue[] = [];

  for (const document of documents) {
    for (
      const targetId
      of collectRelationIds(document)
    ) {
      if (knownIds.has(targetId)) {
        continue;
      }

      issues.push({
        ruleId:
          "content/missing-relation-target",
        severity: "error",
        documentId: document.id,
        sourcePath:
          document.sourcePath,
        message:
          `Relation target ` +
          `"${targetId}" does not exist.`,
      });
    }
  }

  return issues;
}
```

---

# 30. 자기 참조 검증

```ts
export function validateSelfRelations(
  documents: readonly ContentDocument[],
): ValidationIssue[] {
  const issues: ValidationIssue[] = [];

  for (const document of documents) {
    for (
      const targetId
      of collectRelationIds(document)
    ) {
      if (targetId !== document.id) {
        continue;
      }

      issues.push({
        ruleId:
          "content/self-relation",
        severity: "error",
        documentId: document.id,
        sourcePath:
          document.sourcePath,
        message:
          `Document "${document.id}" ` +
          `cannot reference itself.`,
      });
    }
  }

  return issues;
}
```

